CREATE TABLE role (id BINARY(16) NOT NULL, name VARCHAR(50) NOT NULL, description VARCHAR(150) NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_role_name UNIQUE (name));
CREATE TABLE permission (id BINARY(16) NOT NULL, code VARCHAR(100) NOT NULL, description VARCHAR(150) NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_permission_code UNIQUE (code));
CREATE TABLE role_permission (role_id BINARY(16) NOT NULL, permission_id BINARY(16) NOT NULL, PRIMARY KEY (role_id, permission_id), FOREIGN KEY (role_id) REFERENCES role(id), FOREIGN KEY (permission_id) REFERENCES permission(id));
CREATE TABLE user_account (
 id BINARY(16) NOT NULL, username VARCHAR(40) NOT NULL, email_lookup CHAR(64) NOT NULL, email_ciphertext BLOB NOT NULL, email_nonce BINARY(12) NOT NULL, password_hash VARCHAR(255) NOT NULL,
 status ENUM('PENDING','ACTIVE','BLOCKED','INACTIVE') NOT NULL DEFAULT 'PENDING', failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, locked_until TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
 PRIMARY KEY (id), CONSTRAINT uk_user_username UNIQUE (username), CONSTRAINT uk_user_email_lookup UNIQUE (email_lookup));
CREATE TABLE user_role (user_id BINARY(16) NOT NULL, role_id BINARY(16) NOT NULL, PRIMARY KEY (user_id, role_id), FOREIGN KEY (user_id) REFERENCES user_account(id), FOREIGN KEY (role_id) REFERENCES role(id));
CREATE TABLE user_session (id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, token_hash CHAR(64) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), CONSTRAINT uk_session_token_hash UNIQUE (token_hash), FOREIGN KEY (user_id) REFERENCES user_account(id));
CREATE TABLE password_reset_token (id BINARY(16) NOT NULL, user_id BINARY(16) NOT NULL, token_hash CHAR(64) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, used_at TIMESTAMP(6) NULL, PRIMARY KEY (id), CONSTRAINT uk_reset_token_hash UNIQUE (token_hash), FOREIGN KEY (user_id) REFERENCES user_account(id));
CREATE TABLE client (id BINARY(16) NOT NULL, client_type ENUM('PERSON','COMPANY') NOT NULL, name_ciphertext BLOB NOT NULL, name_nonce BINARY(12) NOT NULL, created_by BINARY(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), FOREIGN KEY (created_by) REFERENCES user_account(id));
CREATE TABLE client_identification (id BINARY(16) NOT NULL, client_id BINARY(16) NOT NULL, type VARCHAR(20) NOT NULL, value_lookup CHAR(64) NOT NULL, value_ciphertext BLOB NOT NULL, value_nonce BINARY(12) NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_client_identity UNIQUE (type, value_lookup), FOREIGN KEY (client_id) REFERENCES client(id));
CREATE TABLE client_contact (id BINARY(16) NOT NULL, client_id BINARY(16) NOT NULL, contact_type ENUM('EMAIL','PHONE','ADDRESS') NOT NULL, value_lookup CHAR(64) NULL, value_ciphertext BLOB NOT NULL, value_nonce BINARY(12) NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY (id), FOREIGN KEY (client_id) REFERENCES client(id));
CREATE TABLE vehicle (id BINARY(16) NOT NULL, plate VARCHAR(12) NOT NULL, vin VARCHAR(17) NULL, brand VARCHAR(60) NOT NULL, model VARCHAR(60) NOT NULL, vehicle_year SMALLINT UNSIGNED NOT NULL, PRIMARY KEY (id), CONSTRAINT uk_vehicle_plate UNIQUE (plate), CONSTRAINT uk_vehicle_vin UNIQUE (vin), CONSTRAINT ck_vehicle_year CHECK (vehicle_year BETWEEN 1900 AND 2099));
CREATE TABLE client_vehicle (id BINARY(16) NOT NULL, client_id BINARY(16) NOT NULL, vehicle_id BINARY(16) NOT NULL, relationship_type ENUM('OWNER','RESPONSIBLE','POSSESSOR') NOT NULL, starts_on DATE NOT NULL, ends_on DATE NULL, PRIMARY KEY (id), FOREIGN KEY (client_id) REFERENCES client(id), FOREIGN KEY (vehicle_id) REFERENCES vehicle(id));
